"use client"

import { useEffect, useRef, useCallback } from "react"

interface LightRaysProps {
  enabledWaves?: ("top" | "middle" | "bottom")[]
  rayCount?: number[] | number
  interactive?: boolean
  parallax?: boolean
  animationSpeed?: number
}

interface Ray {
  x: number
  y: number
  originalY: number
  length: number
  speed: number
  angle: number
  opacity: number
  width: number
  wave: "top" | "middle" | "bottom"
  phase: number
  amplitude: number
  frequency: number
  pulsePhase: number
}

export function LightRaysBackground({
  enabledWaves = ["top", "middle", "bottom"],
  rayCount = [8, 12, 16],
  interactive = true,
  parallax = true,
  animationSpeed = 1,
}: LightRaysProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const mouseRef = useRef({ x: 0, y: 0 })
  const scrollRef = useRef(0)

  const getRayCount = useCallback(
    (wave: "top" | "middle" | "bottom") => {
      const index = wave === "top" ? 0 : wave === "middle" ? 1 : 2
      return Array.isArray(rayCount) ? rayCount[index] : rayCount
    },
    [rayCount],
  )

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return

    const ctx = canvas.getContext("2d")
    if (!ctx) return

    let animationFrameId: number
    let rays: Ray[] = []

    const resize = () => {
      canvas.width = window.innerWidth
      canvas.height = window.innerHeight
    }

    const createRays = () => {
      rays = []

      enabledWaves.forEach((wave) => {
        const count = getRayCount(wave)

        const yRange =
          wave === "top"
            ? [0, canvas.height * 0.33]
            : wave === "middle"
              ? [canvas.height * 0.33, canvas.height * 0.66]
              : [canvas.height * 0.66, canvas.height]

        for (let i = 0; i < count; i++) {
          const y = yRange[0] + Math.random() * (yRange[1] - yRange[0])
          
          rays.push({
            x: Math.random() * canvas.width,
            y,
            originalY: y,
            length: 120 + Math.random() * 180,
            speed: (0.2 + Math.random() * 0.4) * animationSpeed,
            angle: Math.random() * Math.PI * 0.3 - Math.PI * 0.15,
            opacity: 0.08 + Math.random() * 0.12,
            width: 1.5 + Math.random() * 3,
            wave,
            phase: Math.random() * Math.PI * 2,
            amplitude: 2 + Math.random() * 3,
            frequency: 0.001 + Math.random() * 0.0015,
            pulsePhase: Math.random() * Math.PI * 2,
          })
        }
      })
    }

    const animate = (time: number) => {
      ctx.clearRect(0, 0, canvas.width, canvas.height)

      rays.forEach((ray) => {
        // Light ray wave motion
        const waveMotion = Math.sin(time * ray.frequency + ray.phase) * ray.amplitude
        ray.y = ray.originalY + waveMotion
        ray.x += Math.cos(ray.angle) * ray.speed

        // Pulsing effect for rays
        const pulse = (Math.sin(time * 0.002 + ray.pulsePhase) + 1) * 0.5
        const currentOpacity = ray.opacity * (0.8 + pulse * 0.4)

        // Parallax effect based on scroll
        if (parallax) {
          const parallaxFactor = ray.wave === "top" ? 0.1 : ray.wave === "middle" ? 0.05 : 0.02
          ray.y += scrollRef.current * parallaxFactor
        }

        // Interactive effect
        if (interactive) {
          const dx = mouseRef.current.x - ray.x
          const dy = mouseRef.current.y - ray.y
          const dist = Math.sqrt(dx * dx + dy * dy)

          if (dist < 200) {
            const influence = (1 - dist / 200) * 0.4
            ray.angle += Math.sin(time * 0.005) * influence * 0.05
          }
        }

        // Wrap around screen
        if (ray.x < -ray.length) ray.x = canvas.width + ray.length
        if (ray.x > canvas.width + ray.length) ray.x = -ray.length

        // Calculate ray end points
        const endX = ray.x + Math.cos(ray.angle) * ray.length
        const endY = ray.y + Math.sin(ray.angle) * ray.length

        // Use your exact same color scheme but as light rays
        const gradient = ctx.createLinearGradient(ray.x, ray.y, endX, endY)

        const isTopWave = ray.wave === "top"
        const isMiddleWave = ray.wave === "middle"

        if (isTopWave) {
          // Navy blue light rays
          gradient.addColorStop(0, `rgba(30, 64, 175, 0)`)
          gradient.addColorStop(0.3, `rgba(30, 64, 175, ${currentOpacity * 0.7})`)
          gradient.addColorStop(0.5, `rgba(30, 64, 175, ${currentOpacity})`)
          gradient.addColorStop(0.7, `rgba(34, 197, 94, ${currentOpacity * 0.6})`)
          gradient.addColorStop(1, `rgba(34, 197, 94, 0)`)
        } else if (isMiddleWave) {
          // Green light rays
          gradient.addColorStop(0, `rgba(34, 197, 94, 0)`)
          gradient.addColorStop(0.3, `rgba(34, 197, 94, ${currentOpacity * 0.8})`)
          gradient.addColorStop(0.5, `rgba(34, 197, 94, ${currentOpacity})`)
          gradient.addColorStop(0.7, `rgba(30, 64, 175, ${currentOpacity * 0.7})`)
          gradient.addColorStop(1, `rgba(30, 64, 175, 0)`)
        } else {
          // Dark navy with subtle green light rays
          gradient.addColorStop(0, `rgba(20, 30, 70, 0)`)
          gradient.addColorStop(0.4, `rgba(20, 30, 70, ${currentOpacity * 0.8})`)
          gradient.addColorStop(0.6, `rgba(20, 30, 70, ${currentOpacity * 0.6})`)
          gradient.addColorStop(0.8, `rgba(100, 180, 100, ${currentOpacity * 0.4})`)
          gradient.addColorStop(1, `rgba(100, 180, 100, 0)`)
        }

        // Draw the light ray
        ctx.beginPath()
        ctx.moveTo(ray.x, ray.y)
        ctx.lineTo(endX, endY)
        ctx.strokeStyle = gradient
        ctx.lineWidth = ray.width
        ctx.lineCap = "round"
        ctx.stroke()

        // Add a subtle glow effect
        ctx.beginPath()
        ctx.moveTo(ray.x, ray.y)
        ctx.lineTo(endX, endY)
        ctx.strokeStyle = isTopWave 
          ? `rgba(30, 64, 175, ${currentOpacity * 0.3})`
          : isMiddleWave 
          ? `rgba(34, 197, 94, ${currentOpacity * 0.3})`
          : `rgba(20, 30, 70, ${currentOpacity * 0.3})`
        ctx.lineWidth = ray.width * 2
        ctx.lineCap = "round"
        ctx.stroke()
      })

      animationFrameId = requestAnimationFrame(animate)
    }

    const handleMouseMove = (e: MouseEvent) => {
      mouseRef.current = { x: e.clientX, y: e.clientY }
    }

    const handleScroll = () => {
      scrollRef.current = window.scrollY
    }

    resize()
    createRays()
    animationFrameId = requestAnimationFrame(animate)

    window.addEventListener("resize", () => {
      resize()
      createRays()
    })

    if (interactive) {
      window.addEventListener("mousemove", handleMouseMove)
    }

    if (parallax) {
      window.addEventListener("scroll", handleScroll)
    }

    return () => {
      cancelAnimationFrame(animationFrameId)
      window.removeEventListener("resize", resize)
      window.removeEventListener("mousemove", handleMouseMove)
      window.removeEventListener("scroll", handleScroll)
    }
  }, [enabledWaves, getRayCount, interactive, parallax, animationSpeed])

  return <canvas ref={canvasRef} className="fixed inset-0 pointer-events-none z-0" style={{ opacity: 0.7 }} />
}